import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';
import React from 'react';
import ReactDOM from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import {CpuLoadChart} from './monitoring/CpuLoadChart';
import {createMockCpuLoadSource, type CpuLoadSource} from './monitoring/cpuLoadSource';

const mode = new URLSearchParams(location.search).get('mode');
const base = createMockCpuLoadSource();
const source: CpuLoadSource =
    mode === 'empty'
        ? {loadHistory: async () => ({timestamps: [], values: []}), subscribe: base.subscribe}
        : mode === 'bulk'
          ? {
                loadHistory: (f, t, s) => base.loadHistory(f - 3 * 3600_000, t - 3 * 3600_000, s),
                subscribe(cb) {
                    // через 1.5 c приходит пачка за 3 часа (10 800 точек), как после возврата во вкладку
                    const timer = setTimeout(() => {
                        const now = Math.floor(Date.now() / 1000) * 1000;
                        const timestamps: number[] = [];
                        const values: number[] = [];
                        for (let ts = now - 3 * 3600_000 + 1000; ts <= now; ts += 1000) {
                            timestamps.push(ts);
                            values.push(90);
                        }
                        cb({timestamps, values});
                    }, 1500);
                    return () => clearTimeout(timer);
                },
            }
          : base;

function Harness() {
    const [theme, setTheme] = React.useState<'light' | 'dark'>('light');
    const [mounted, setMounted] = React.useState(true);
    const [width, setWidth] = React.useState<string>('100%');
    (window as any).__h = {setTheme, setMounted, setWidth};
    return (
        <ThemeProvider theme={theme}>
            <div style={{padding: 24, width, boxSizing: 'border-box'}} id="wrap">
                {mounted && <CpuLoadChart source={source} />}
            </div>
        </ThemeProvider>
    );
}
ReactDOM.createRoot(document.getElementById('root')!).render(<React.StrictMode><Harness /></React.StrictMode>);
EOF
