  console.log(mode, 'before', JSON.stringify(await statsOf(page)));
  await page.waitForTimeout(2500);
  console.log(mode, 'after', JSON.stringify(await statsOf(page)));
  await page.screenshot({path: `${out}/${mode}.png`});
  await page.close();
}

// perf: long tasks during live updates + hover
const page = await browser.newPage({viewport: {width: 1400, height: 700}});
page.on('pageerror', (e) => errors.push('perf pageerror: ' + e.message));
await page.goto('http://localhost:41739/verify.html');
