await page.waitForTimeout(1500);
await page.evaluate(() => {
  window.__lt = [];
  new PerformanceObserver((l) => l.getEntries().forEach((e) => window.__lt.push(Math.round(e.duration)))).observe({type: 'longtask'});
});
const box = await page.locator('.cpu-load-chart .u-over').boundingBox();
const t0 = Date.now();
for (let i = 0; i < 300; i++) {
  await page.mouse.move(box.x + (box.width * (i % 100)) / 100, box.y + box.height / 2);
}
const hoverMs = Date.now() - t0;
await page.waitForTimeout(5000);
console.log('300 mousemoves took', hoverMs, 'ms; long tasks (>50ms) during ~6s of live updates + hover:', JSON.stringify(await page.evaluate(() => window.__lt)));
const pts = await page.evaluate(async () => {
  const t = performance.now();
  // время одного кадра перерисовки после resize (полный пересчёт путей на 86k точек)
  document.getElementById('wrap').style.width = '900px';
  await new Promise((r) => setTimeout(r, 200));
  return Math.round(performance.now() - t);
});
console.log('errors', JSON.stringify(errors));
await browser.close();
EOF
